== rune_gnosis body snippet ==
  .st-num{font-family:'Cinzel',serif;font-size:0.58rem;letter-spacing:0.22em;color:#8a6e30;text-transform:uppercase;min-width:1.6rem;}
  .st-act{font-family:'Cinzel',serif;font-size:0.58rem;letter-spacing:0.26em;color:rgba(201,168,76,0.55);text-transform:uppercase;}
  .st-rule{flex:1;height:0.5px;background:rgba(201,168,76,0.14);}
  .st-body{border-left:1px solid rgba(201,168,76,0.1);padding-left:1.1rem;}
  .ln{font-size:0.95rem;line-height:1.95;color:#e8e2d5;opacity:0.87;}
  .ln-k{font-style:italic;color:#c9a84c;opacity:0.92;margin-top:0.2rem;}
  .ln-gap{height:0.5rem;}
  .prelude{margin:0 0 2.5rem;padding:1.2rem 1.4rem;border:0.5px solid rgba(201,168,76,0.14);border-radius:3px;}
  .prelude .ln{font-style:italic;color:#a09880;}
  .prelude .ln-k{color:#c9a84c;}
  .closure{margin-top:3rem;padding:2rem 1.8rem;border:0.5px solid rgba(201,168,76,0.18);border-radius:4px;background:rgba(201,168,76,0.03);text-align:center;}
  .cl-title{font-family:'Cinzel',serif;font-size:0.72rem;letter-spacing:0.3em;color:#c9a84c;text-transform:uppercase;margin-bottom:1.2rem;}
  .closure .ln{text-align:center;}
  .closure .ln-k{text-align:center;}
  .final{margin-top:2.5rem;text-align:center;font-family:'Cinzel',serif;font-size:0.6rem;letter-spacing:0.38em;color:#8a6e30;text-transform:uppercase;line-height:2.2;}
</style>

<div class="wrap">
  <div class="header">
    <div class="h-eyebrow">Canto I · Vinit</div>
    <div class="h-title">The Rune Gnosis</div>
    <div class="h-sub">to be recited while hanging on the wind-stripped branch, nine nights, without bread or mead</div>
    <div class="divider"><div class="div-line"></div><span class="div-sym">᚛</span><span class="div-sym">ᚠ</span><span class="div-sym">᚜</span><div class="div-line"></div></div>
    <div class="h-eyebrow" style="margin-top:0;">Ginnungagap — Before the first rune was carved</div>
  </div>
